const QUIZ_DATA = {"title": "Core Java MCQ Practice Bank – CDAC PGCP-AC (Java 17)", "description": "200 medium-to-hard MCQs aligned to CDAC syllabus (Sessions 1–30)", "sections": [{"id": 1, "title": "Java Basics, Data Types, Operators, Control, Arrays", "range": "Q1–Q22"}, {"id": 2, "title": "OOP, Static, References, Constructors, Memory, Records", "range": "Q23–Q40"}, {"id": 3, "title": "Inheritance, Polymorphism, Packages, Access Control, Casting", "range": "Q41–Q62"}, {"id": 4, "title": "String Class, StringBuilder/Buffer, Wrapper Classes", "range": "Q63–Q82"}, {"id": 5, "title": "Enum, Sealed, Final, Pattern Matching, Inner Classes", "range": "Q83–Q94"}, {"id": 6, "title": "Abstract Class, Interfaces, Garbage Collection", "range": "Q95–Q110"}, {"id": 7, "title": "Exception Handling", "range": "Q111–Q126"}, {"id": 8, "title": "File I/O, Serialization, Object Class, Date-Time API", "range": "Q127–Q136"}, {"id": 9, "title": "Generics, Collections, Hashing, Sorting", "range": "Q137–Q164"}, {"id": 10, "title": "Lambda, Functional Interfaces, Stream API", "range": "Q165–Q182"}, {"id": 11, "title": "Multithreading, Synchronization, Reflection", "range": "Q183–Q192"}, {"id": 12, "title": "JDBC and DAO Pattern", "range": "Q193–Q200"}], "questions": [{"id": 1, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nbyte b = 10;\nb = b + 5;\nSystem.out.println(b);", "options": ["15", "Compile-time error", "Runtime ArithmeticException", "5"], "answer": 1, "explanation": "b + 5 is an int; assigning to byte needs a cast (lossy conversion)."}, {"id": 2, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nint x = 5;\nint y = x++ + ++x;\nSystem.out.println(x + \" \" + y);", "options": ["6 11", "7 12", "7 11", "6 12"], "answer": 1, "explanation": "x++ gives 5 (x=6), ++x makes x=7 and gives 7; y = 12, x = 7."}, {"id": 3, "section": 1, "type": "Trap", "question": "What is the output of the following code?\n\nSystem.out.println('a' + 1 + \"b\" + 'c');", "options": ["abc", "98bc", "bbc", "a1bc"], "answer": 1, "explanation": "'a'+1 is int 98; then string concatenation gives \"98b\", then \"98bc\"."}, {"id": 4, "section": 1, "type": "Trap", "question": "What is the output of the following code?\n\nchar c = 'A';\nc += 2;\nSystem.out.println(c);", "options": ["C", "67", "Compile-time error", "A2"], "answer": 0, "explanation": "Compound assignment (+=) has an implicit cast, so c becomes 'C'."}, {"id": 5, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nint i = 10;\nlong l = i;\nfloat f = l;\nint j = (int) 3.99;\nSystem.out.println(f + \" \" + j);", "options": ["10 3", "10.0 3", "10.0 4", "Compile-time error"], "answer": 1, "explanation": "f = 10.0 (float), and (int)3.99 truncates to 3."}, {"id": 6, "section": 1, "type": "Trap", "question": "What happens with the following code?\n\nfinal int a = 10;\nint c = 10;\nbyte b1 = a; // line 1\nbyte b2 = c; // line 2", "options": ["Both lines fail", "Only line 1 fails", "Only line 2 fails", "Both compile"], "answer": 2, "explanation": "A final variable with a compile-time constant that fits in byte can be narrowed implicitly; the non-final c cannot."}, {"id": 7, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nint x = Integer.MAX_VALUE;\nx++;\nSystem.out.println(x);", "options": ["2147483648", "-2147483648", "ArithmeticException", "0"], "answer": 1, "explanation": "Integer overflow wraps around silently."}, {"id": 8, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nSystem.out.println(10/3 + 10%3 + 10.0/4);", "options": ["6.5", "6.83", "7.0", "5.5"], "answer": 0, "explanation": "3 + 1 + 2.5 = 6.5."}, {"id": 9, "section": 1, "type": "Trap", "question": "What is the output of the following code?\n\nSystem.out.println((-7 % 3) + (7 % -3));", "options": ["0", "-2", "2", "-1"], "answer": 0, "explanation": "Result of % takes the sign of the dividend: -1 + 1 = 0."}, {"id": 10, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nint n = 2;\nswitch (n) {\n  case 1: System.out.print(\"A\");\n  case 2: System.out.print(\"B\");\n  case 3: System.out.print(\"C\"); break;\n  default: System.out.print(\"D\");\n}", "options": ["B", "BC", "BCD", "C"], "answer": 1, "explanation": "Falls through from case 2 to case 3 until break: BC."}, {"id": 11, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nint k = 4;\nint res = switch (k) {\n  case 1, 2 -> 10;\n  case 3, 4 -> { int t = k * 2; yield t + 1; }\n  default -> 0;\n};\nSystem.out.println(res);", "options": ["8", "9", "10", "0"], "answer": 1, "explanation": "t = 8, yield 8 + 1 = 9."}, {"id": 12, "section": 1, "type": "Concept", "question": "Which statement about switch expressions (Java 14+) is correct?", "options": ["A switch expression on an int must be exhaustive, so it needs a default (or cover all values)", "Arrow-form cases need a break statement", "Arrow-form cases fall through to the next case", "A switch expression cannot produce a value from a block"], "answer": 0, "explanation": "Switch expressions must be exhaustive; arrow cases never fall through and need no break."}, {"id": 13, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nint[] a = {1, 2, 3};\nint[] b = a;\nb[0] = 99;\nSystem.out.println(a[0] + \" \" + (a == b));", "options": ["1 true", "99 true", "99 false", "1 false"], "answer": 1, "explanation": "Arrays are objects; b and a refer to the same array."}, {"id": 14, "section": 1, "type": "Trap", "question": "What is the output of the following code?\n\nint[][] m = new int[3][];\nSystem.out.println(m[0]);", "options": ["0", "null", "[I@1b6d3586 (some hash)", "NullPointerException"], "answer": 1, "explanation": "Rows of a jagged array default to null; printing null prints \"null\"."}, {"id": 15, "section": 1, "type": "Output", "question": "Find the value of s:\n\nint[][] m = {{1,2,3},{4,5,6},{7,8,10}};\nint s = 0;\nfor (int i = 0; i < 3; i++) s += m[i][i];\nSystem.out.println(s);", "options": ["15", "16", "17", "22"], "answer": 1, "explanation": "1 + 5 + 10 = 16."}, {"id": 16, "section": 1, "type": "Concept", "question": "Which is a valid Java identifier?", "options": ["2ndVar", "my-var", "_value", "class"], "answer": 2, "explanation": "Identifiers can start with letter, _ or $; they cannot be keywords or contain '-'."}, {"id": 17, "section": 1, "type": "Trap", "question": "Which of the following is a reserved literal and NOT a keyword?", "options": ["goto", "null", "const", "strictfp"], "answer": 1, "explanation": "null (like true and false) is a literal; goto, const are reserved keywords."}, {"id": 18, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nint x = 0b101 + 010 + 0x10;\nSystem.out.println(x);", "options": ["26", "29", "31", "23"], "answer": 1, "explanation": "5 + 8 (octal 010) + 16 = 29."}, {"id": 19, "section": 1, "type": "Trap", "question": "What is the output of the following code?\n\nSystem.out.println(0.1 + 0.2 == 0.3);\nSystem.out.println(0.5 + 0.25 == 0.75);", "options": ["true true", "false true", "false false", "true false"], "answer": 1, "explanation": "0.1+0.2 is not exactly 0.3 in binary floating point; 0.5 and 0.25 are exactly representable."}, {"id": 20, "section": 1, "type": "Output", "question": "What is the output of the following code?\n\nclass T {\n  int i; boolean b; String s; char c; double d;\n  void p() { System.out.println(i+\" \"+b+\" \"+s+\" \"+(int)c+\" \"+d); }\n}\nnew T().p();", "options": ["0 false null 0 0.0", "0 false (empty) 0 0.0", "Compile-time error (uninitialized variables)", "null false null 0 0"], "answer": 0, "explanation": "Instance variables get default values; (int)'\\u0000' = 0."}, {"id": 21, "section": 1, "type": "Concept", "question": "Which statement about the JVM is correct?", "options": ["The JRE contains the javac compiler", "The JIT compiler is part of the JVM and compiles frequently used bytecode to native code at runtime", "Metaspace is a part of the Java heap", "The class loader subsystem executes the bytecode"], "answer": 1, "explanation": "JRE does not include javac; Metaspace is native memory; the execution engine runs bytecode."}, {"id": 22, "section": 1, "type": "Scenario", "question": "A student saves 'public class Test { ... }' in a file named Demo.java and compiles it. What happens?", "options": ["Compiles; run with java Demo", "Compile-time error: public class Test must be declared in Test.java", "Compiles but fails at runtime", "Compiles; run with java Test"], "answer": 1, "explanation": "A public top-level class must live in a file with the same name."}, {"id": 23, "section": 2, "type": "Output", "question": "What is the output of the following code?\n\nclass Counter {\n  static int s = 0; int i = 0;\n  Counter() { s++; i++; }\n}\nCounter a = new Counter(), b = new Counter(), c = new Counter();\nSystem.out.println(a.s + \" \" + a.i + \" \" + c.i);", "options": ["3 3 3", "3 1 1", "1 1 1", "3 3 1"], "answer": 1, "explanation": "static s is shared (3); instance i is per object (1)."}, {"id": 24, "section": 2, "type": "Scenario", "question": "A Student class has String name (instance) and a static method showCollege() that prints name. What happens?", "options": ["Prints null", "Prints the college name", "Compile-time error: non-static variable cannot be referenced from a static context", "NullPointerException at runtime"], "answer": 2, "explanation": "Static methods have no 'this', so they cannot access instance members directly."}, {"id": 25, "section": 2, "type": "Output", "question": "What is the output of the following code?\n\nstatic void change(int[] arr, int n) {\n  arr[0] = 50; n = 50; arr = new int[]{9, 9};\n}\n// main\nint[] a = {1, 2}; int n = 1;\nchange(a, n);\nSystem.out.println(a[0] + \" \" + n + \" \" + a.length);", "options": ["1 1 2", "50 50 2", "50 1 2", "9 1 2"], "answer": 2, "explanation": "Array contents change through the reference; n is a copy; reassigning arr affects only the local copy."}, {"id": 26, "section": 2, "type": "Trap", "question": "What is the output of the following code?\n\nstatic void swap(Student s1, Student s2) { Student t = s1; s1 = s2; s2 = t; }\n// main\nStudent a = new Student(\"Ann\"), b = new Student(\"Ben\");\nswap(a, b);\nSystem.out.println(a.name + \" \" + b.name);", "options": ["Ben Ann", "Ann Ben", "Compile-time error", "NullPointerException"], "answer": 1, "explanation": "Java is always pass-by-value; the references are copied, so swapping copies does nothing."}, {"id": 27, "section": 2, "type": "Output", "question": "What is the output of the following code?\n\nclass Box { int v = 1; }\nstatic void m(Box b) { b.v = 5; b = new Box(); b.v = 9; }\n// main\nBox x = new Box(); m(x);\nSystem.out.println(x.v);", "options": ["1", "5", "9", "Compile-time error"], "answer": 1, "explanation": "b.v = 5 changes the shared object; then b points to a new Box locally."}, {"id": 28, "section": 2, "type": "Output", "question": "What is the output of the following code?\n\nclass A {\n  A() { this(5); System.out.print(\"A0 \"); }\n  A(int x) { System.out.print(\"A1 \"); }\n}\nnew A();", "options": ["A0 A1", "A1 A0", "A1", "Compile-time error"], "answer": 1, "explanation": "this(5) runs A(int) first, then the rest of A()."}, {"id": 29, "section": 2, "type": "Trap", "question": "What happens with the following code?\n\nclass Emp { Emp(String n) { } }\nEmp e = new Emp();", "options": ["Compiles; name is null", "Compile-time error: no suitable constructor", "Runtime error", "Default constructor is still generated"], "answer": 1, "explanation": "Defining any constructor removes the default one."}, {"id": 30, "section": 2, "type": "Output", "question": "What is the output of the following code?\n\nclass T {\n  static { System.out.print(\"S \"); }\n  { System.out.print(\"I \"); }\n  T() { System.out.print(\"C \"); }\n  public static void main(String[] a) { new T(); new T(); }\n}", "options": ["S I C I C", "I C S I C C", "S I C", "I C I C"], "answer": 0, "explanation": "Static block runs once at class load; instance block runs before every constructor body."}, {"id": 31, "section": 2, "type": "Concept", "question": "For 'Student s = new Student();' declared inside a method, which is correct?", "options": ["Both s and the object are on the stack", "s is on the heap, object on the stack", "s (the reference) is on the stack, the object is on the heap", "Both are always on the heap"], "answer": 2, "explanation": "Local reference on the stack, object on the heap."}, {"id": 32, "section": 2, "type": "Scenario", "question": "A recursive factorial method has no base case. What will most likely happen when it is called?", "options": ["OutOfMemoryError", "StackOverflowError", "StackOverflowException (checked)", "Compiler warning only, returns 0"], "answer": 1, "explanation": "Endless recursion exhausts the stack: StackOverflowError (an Error, not an Exception)."}, {"id": 33, "section": 2, "type": "Trap", "question": "What is the output of the following code?\n\nclass S { static int v = 10; }\nS s = null;\nSystem.out.println(s.v);", "options": ["NullPointerException", "10", "null", "Compile-time error"], "answer": 1, "explanation": "Static members are resolved by the declared type, so no NPE."}, {"id": 34, "section": 2, "type": "Output", "question": "What is the output of the following code?\n\nclass P { int id; P(int i) { id = i; } }\nP p1 = new P(1), p2 = new P(1);\nSystem.out.println(p1 == p2);\nSystem.out.println(p1.equals(p2));", "options": ["true true", "true false", "false false", "false true"], "answer": 2, "explanation": "Default equals() is identity comparison, same as ==."}, {"id": 35, "section": 2, "type": "Output", "question": "What is the output of the following code?\n\nrecord Point(int x, int y) { }\nSystem.out.println(new Point(1, 2));", "options": ["Point@1b6d3586", "Point[x=1, y=2]", "Point(1,2)", "Compile-time error"], "answer": 1, "explanation": "Records auto-generate a readable toString."}, {"id": 36, "section": 2, "type": "Concept", "question": "Which statement about records is TRUE?", "options": ["Record fields can be changed using auto-generated setters", "A record can extend another class", "A record can implement interfaces and declare static methods", "A record's fields are non-final by default"], "answer": 2, "explanation": "Records are final, fields are private final, they extend java.lang.Record, and can implement interfaces."}, {"id": 37, "section": 2, "type": "Trap", "question": "Given 'record Student(int roll, String name) {}', how do you read name from another class?", "options": ["s.getName()", "s.name()", "s.name", "s.get(\"name\")"], "answer": 1, "explanation": "Accessors are named like the component: name()."}, {"id": 38, "section": 2, "type": "Concept", "question": "Best description of the difference between a static variable and a reference variable:", "options": ["A static variable has one copy per class shared by all objects; a reference variable holds a reference to an object (and may itself be static or not)", "They are the same thing", "Reference variables are shared by all objects of a class", "Static variables can only be of primitive type"], "answer": 0, "explanation": "Static means one per class; a reference variable only stores a reference."}, {"id": 39, "section": 2, "type": "Scenario", "question": "What is the output of the following code?\n\nclass BankAccount { static String bankName = \"ABC\"; }\nBankAccount a1 = new BankAccount(), a2 = new BankAccount();\na1.bankName = \"XYZ\";\nSystem.out.println(a2.bankName);", "options": ["ABC", "XYZ", "null", "Compile-time error"], "answer": 1, "explanation": "Access through any reference changes the single shared static variable."}, {"id": 40, "section": 2, "type": "Trap", "question": "What is wrong with the following constructor?\n\nStudent() {\n  System.out.println(\"x\");\n  this(5);\n}", "options": ["Prints x, then continues normally", "Compile-time error: call to this() must be the first statement", "Runtime error", "Infinite recursion"], "answer": 1, "explanation": "In Java 17, this(...)/super(...) must be the first statement."}, {"id": 41, "section": 3, "type": "Trap", "question": "What is the output of the following code?\n\nclass A { int x = 10; void show() { System.out.print(\"A \"); } }\nclass B extends A { int x = 20; void show() { System.out.print(\"B \"); } }\nA obj = new B();\nobj.show();\nSystem.out.println(obj.x);", "options": ["B 20", "B 10", "A 10", "A 20"], "answer": 1, "explanation": "Methods are dynamically dispatched (B); fields are resolved by reference type (A.x = 10)."}, {"id": 42, "section": 3, "type": "Trap", "question": "What is the output of the following code?\n\nclass P { static void hi() { System.out.print(\"P\"); } }\nclass C extends P { static void hi() { System.out.print(\"C\"); } }\nP p = new C();\np.hi();", "options": ["P", "C", "Compile-time error", "Runtime error"], "answer": 0, "explanation": "Static methods are hidden, not overridden; resolved by reference type."}, {"id": 43, "section": 3, "type": "Output", "question": "What is the output of the following code?\n\nclass A { A() { System.out.print(\"A \"); } }\nclass B extends A { B() { System.out.print(\"B \"); } }\nclass C extends B { C() { System.out.print(\"C \"); } }\nnew C();", "options": ["C B A", "A B C", "C", "A C"], "answer": 1, "explanation": "Constructors run top-down: superclass first."}, {"id": 44, "section": 3, "type": "Trap", "question": "What is the output of the following code?\n\nclass A { A() { show(); } void show() { System.out.print(\"A\"); } }\nclass B extends A {\n  int v = 5;\n  void show() { System.out.print(\"v=\" + v); }\n}\nnew B();", "options": ["v=5", "v=0", "A", "NullPointerException"], "answer": 1, "explanation": "Superclass constructor runs before B's field initializers, so v is still 0 (overridden method called early)."}, {"id": 45, "section": 3, "type": "Trap", "question": "Only these overloads exist: f(long), f(Integer), f(Object). What does f(5) call?", "options": ["f(long)", "f(Integer)", "f(Object)", "Compile-time error"], "answer": 0, "explanation": "Widening primitive conversion is tried before boxing."}, {"id": 46, "section": 3, "type": "Trap", "question": "What is the output of the following code?\n\nstatic void m(Object o) { System.out.print(\"O\"); }\nstatic void m(String s) { System.out.print(\"S\"); }\nm(null);", "options": ["O", "S", "Compile-time error: ambiguous", "NullPointerException"], "answer": 1, "explanation": "The most specific type (String) is chosen. It would be ambiguous only if two unrelated types like String and StringBuilder were present."}, {"id": 47, "section": 3, "type": "Concept", "question": "Parent has 'protected Number get() throws IOException'. Which override in a subclass is ILLEGAL?", "options": ["public Integer get()", "protected Number get() throws FileNotFoundException", "protected Number get() throws Exception", "protected Integer get()"], "answer": 2, "explanation": "An overriding method cannot throw broader checked exceptions. Wider access and covariant return types are fine."}, {"id": 48, "section": 3, "type": "Trap", "question": "What is the output of the following code?\n\nclass A { void f(A a) { System.out.print(\"A-A\"); } }\nclass B extends A { void f(B b) { System.out.print(\"B-B\"); } }\nA obj = new B();\nobj.f(new B());", "options": ["B-B", "A-A", "Compile-time error", "Runtime error"], "answer": 1, "explanation": "B.f(B) is an overload, not an override. A reference of type A only sees f(A), which is not overridden."}, {"id": 49, "section": 3, "type": "Output", "question": "What is the output of the following code?\n\nclass Animal { void sound() { } }\nclass Dog extends Animal { void sound() { System.out.print(\"Woof\"); } void fetch() { System.out.print(\"fetch\"); } }\nAnimal a = new Dog();\na.fetch();", "options": ["fetch", "ClassCastException", "Compile-time error", "Woof"], "answer": 2, "explanation": "Methods are checked against the reference type (Animal), which has no fetch()."}, {"id": 50, "section": 3, "type": "Scenario", "question": "Person p = new Person(); Employee e = (Employee) p; — what happens?", "options": ["Compile-time error", "Compiles; ClassCastException at runtime", "Works; e is null", "NullPointerException"], "answer": 1, "explanation": "The compiler allows the downcast (related types) but the object is not an Employee at runtime."}, {"id": 51, "section": 3, "type": "Output", "question": "What is the output of the following code?\n\nObject o = \"Java\";\nif (o instanceof String s && s.length() > 3)\n  System.out.println(s.toUpperCase());\nelse System.out.println(\"no\");", "options": ["JAVA", "Java", "no", "Compile-time error"], "answer": 0, "explanation": "Pattern matching binds s; the length condition is true for \"Java\" (4 > 3)."}, {"id": 52, "section": 3, "type": "Trap", "question": "What is the output of the following code?\n\nString s = null;\nSystem.out.println(s instanceof String);", "options": ["true", "false", "NullPointerException", "Compile-time error"], "answer": 1, "explanation": "instanceof is false for null; no exception."}, {"id": 53, "section": 3, "type": "Scenario", "question": "Class A in package p1 has 'protected void m()'. Class B extends A in package p2 contains: 'A a = new A(); a.m();' and 'this.m();'. Which is true?", "options": ["Both compile", "Only this.m() compiles", "Only a.m() compiles", "Neither compiles"], "answer": 1, "explanation": "Protected access outside the package works only through the subclass type (this/B), not through a plain A reference."}, {"id": 54, "section": 3, "type": "Concept", "question": "A member declared with no access modifier (default) is accessible from:", "options": ["Classes in the same package only", "Subclasses in any package", "Everywhere", "Only the same class"], "answer": 0, "explanation": "Package-private; not even subclasses in other packages."}, {"id": 55, "section": 3, "type": "Concept", "question": "Which is the correct syntax for a static import of sqrt?", "options": ["import static java.lang.Math.sqrt;", "static import java.lang.Math.sqrt;", "import java.lang.static.Math;", "using static java.lang.Math;"], "answer": 0, "explanation": "The syntax is import static ..."}, {"id": 56, "section": 3, "type": "Trap", "question": "What happens with the following code?\n\nimport java.util.*;\npublic class T {\n  public static void main(String[] a) {\n    ConcurrentHashMap<String,Integer> m = new ConcurrentHashMap<>();\n  }\n}", "options": ["Compiles; * imports sub-packages too", "Compile-time error: wildcard does not import sub-packages (java.util.concurrent)", "Runtime error", "Compiles because it is a Map"], "answer": 1, "explanation": "java.util.* covers only classes directly inside java.util."}, {"id": 57, "section": 3, "type": "Output", "question": "What is the output of the following code?\n\nclass P { P() { System.out.print(\"P0 \"); } P(int x) { System.out.print(\"P1 \"); } }\nclass C extends P {\n  C() { super(1); System.out.print(\"C0 \"); }\n  C(int x) { this(); System.out.print(\"C1 \"); }\n}\nnew C(5);", "options": ["P0 C0 C1", "P1 C0 C1", "P1 C1 C0", "P0 P1 C0 C1"], "answer": 1, "explanation": "C(int) → this() → C() → super(1) prints P1, then C0, then C1."}, {"id": 58, "section": 3, "type": "Scenario", "question": "(i) A Car and its Engine (engine destroyed when car is scrapped). (ii) A Department and its Employees (employees continue if department closes). Which relationships apply?", "options": ["(i) Composition, (ii) Aggregation", "(i) Aggregation, (ii) Composition", "(i) Inheritance, (ii) Aggregation", "(i) Association only, (ii) Inheritance"], "answer": 0, "explanation": "Composition = strong lifetime dependency; aggregation = weak."}, {"id": 59, "section": 3, "type": "Trap", "question": "What is the output of the following code?\n\nclass A { private void p() { System.out.print(\"A\"); } void call() { p(); } }\nclass B extends A { void p() { System.out.print(\"B\"); } }\nnew B().call();", "options": ["A", "B", "Compile-time error", "Runtime error"], "answer": 0, "explanation": "Private methods are not inherited or overridden; A.call() calls A's own p()."}, {"id": 60, "section": 3, "type": "Output", "question": "What is the output of the following code?\n\nclass A { String name = \"A\"; }\nclass B extends A {\n  String name = \"B\";\n  void p() { System.out.println(name + super.name + ((A) this).name); }\n}\nnew B().p();", "options": ["BAA", "BBB", "ABB", "BAB"], "answer": 0, "explanation": "name → B, super.name → A, ((A)this).name → A (field by reference type)."}, {"id": 61, "section": 3, "type": "Concept", "question": "Which statement about polymorphism is TRUE?", "options": ["Method overriding is resolved at compile time", "Method overloading is resolved at compile time using the declared types of arguments", "Field access is resolved at runtime based on the object", "Static methods are overridden at runtime"], "answer": 1, "explanation": "Overloading is compile-time; overriding is runtime; fields and static methods are not polymorphic."}, {"id": 62, "section": 3, "type": "Output", "question": "Hierarchy: Person → Employee → Manager.\n\nSystem.out.print(new Manager() instanceof Employee);\nSystem.out.print(\" \");\nSystem.out.print(new Employee() instanceof Manager);", "options": ["true true", "true false", "false true", "false false"], "answer": 1, "explanation": "A Manager is an Employee; an Employee is not a Manager."}, {"id": 63, "section": 4, "type": "Output", "question": "What is the output of the following code?\n\nString a = \"hello\", b = \"hello\", c = new String(\"hello\");\nSystem.out.print((a == b) + \" \" + (a == c) + \" \" + a.equals(c) + \" \" + (a == c.intern()));", "options": ["true false true true", "true true true true", "false false true true", "true false false true"], "answer": 0, "explanation": "Literals share a pool entry; new creates a separate heap object; intern() returns the pooled one."}, {"id": 64, "section": 4, "type": "Trap", "question": "What is the output of the following code?\n\nString s1 = \"ab\";\nString s2 = \"a\" + \"b\";\nString s3 = \"a\";\nString s4 = s3 + \"b\";\nSystem.out.print((s1 == s2) + \" \" + (s1 == s4));", "options": ["true true", "true false", "false false", "false true"], "answer": 1, "explanation": "\"a\"+\"b\" is a compile-time constant (pooled); s3 + \"b\" is computed at runtime (new object)."}, {"id": 65, "section": 4, "type": "Trap", "question": "What is the output of the following code?\n\nfinal String x = \"a\";\nString z = \"a\";\nSystem.out.print(((x + \"b\") == \"ab\") + \" \" + ((z + \"b\") == \"ab\"));", "options": ["true false", "false false", "true true", "false true"], "answer": 0, "explanation": "A final String initialized with a constant makes the concatenation a constant expression."}, {"id": 66, "section": 4, "type": "Output", "question": "What is the output of the following code?\n\nString s = \"java\";\ns.concat(\" rocks\");\ns.toUpperCase();\nSystem.out.println(s);", "options": ["java", "JAVA", "java rocks", "JAVA ROCKS"], "answer": 0, "explanation": "Strings are immutable; the results of concat/toUpperCase were discarded."}, {"id": 67, "section": 4, "type": "Concept", "question": "How many String objects are created by 'String s = new String(\"abc\");' if \"abc\" is not yet in the pool?", "options": ["1", "2", "3", "0"], "answer": 1, "explanation": "One in the pool (literal) and one on the heap (new)."}, {"id": 68, "section": 4, "type": "Output", "question": "What is the output of the following code?\n\nStringBuilder sb = new StringBuilder(\"ab\");\nStringBuilder sb2 = sb;\nsb2.append(\"c\").reverse();\nSystem.out.println(sb);", "options": ["abc", "cba", "ab", "ba"], "answer": 1, "explanation": "Both refer to the same builder: \"abc\" reversed is \"cba\"."}, {"id": 69, "section": 4, "type": "Trap", "question": "What is the output of the following code?\n\nSystem.out.println(new StringBuilder(\"a\").equals(new StringBuilder(\"a\")));\nSystem.out.println(new StringBuilder(\"a\").toString().equals(new StringBuilder(\"a\").toString()));", "options": ["true true", "false true", "false false", "true false"], "answer": 1, "explanation": "StringBuilder does not override equals(); it uses identity."}, {"id": 70, "section": 4, "type": "Output", "question": "What is the output of the following code?\n\nString s = \"Programming\";\nSystem.out.println(s.substring(3, 7) + s.indexOf('m') + s.charAt(s.length() - 1));", "options": ["gram6g", "ogram6g", "gram7g", "ram6g"], "answer": 0, "explanation": "substring(3,7)=\"gram\", indexOf('m')=6, last char 'g'."}, {"id": 71, "section": 4, "type": "Trap", "question": "What is the output of the following code?\n\nString s = \"a,b,,c,,\";\nSystem.out.println(s.split(\",\").length);", "options": ["4", "6", "5", "3"], "answer": 0, "explanation": "Trailing empty strings are removed: [a, b, \"\", c]."}, {"id": 72, "section": 4, "type": "Output", "question": "What is the output of the following code?\n\nString s = \"  Hi  \";\nSystem.out.println(s.trim().length() + s.length());", "options": ["8", "26", "6", "2"], "answer": 0, "explanation": "2 + 6 = 8 (integer addition, not concatenation)."}, {"id": 73, "section": 4, "type": "Trap", "question": "What is the output of the following code?\n\nSystem.out.println(\"Apple\".compareTo(\"apple\"));", "options": ["-32", "32", "-1", "0"], "answer": 0, "explanation": "'A'(65) - 'a'(97) = -32."}, {"id": 74, "section": 4, "type": "Trap", "question": "What is the output of the following code?\n\nInteger a = 127, b = 127, c = 128, d = 128;\nSystem.out.print((a == b) + \" \" + (c == d) + \" \" + c.equals(d));", "options": ["true true true", "true false true", "false false true", "true false false"], "answer": 1, "explanation": "Integer cache covers -128 to 127; 128 creates different objects."}, {"id": 75, "section": 4, "type": "Scenario", "question": "A billing program does: Map<String,Integer> stock = new HashMap<>(); int qty = stock.get(\"pen\"); where \"pen\" was never added. What happens?", "options": ["qty = 0", "qty = null", "NullPointerException at runtime", "Compile-time error"], "answer": 2, "explanation": "get() returns null; auto-unboxing null throws NPE."}, {"id": 76, "section": 4, "type": "Output", "question": "What is the output of the following code?\n\nSystem.out.println(Integer.parseInt(\"12\") + Integer.valueOf(\"3\") + \"4\");", "options": ["154", "1234", "19", "Compile-time error"], "answer": 0, "explanation": "12 + 3 = 15, then + \"4\" gives \"154\"."}, {"id": 77, "section": 4, "type": "Trap", "question": "What is the output of the following code?\n\nInteger a = 5;\nLong b = 5L;\nSystem.out.print(a.equals(b) + \" \" + (a.longValue() == b));", "options": ["true true", "false true", "false false", "true false"], "answer": 1, "explanation": "Integer.equals(Long) is false (different types); the primitive comparison is true."}, {"id": 78, "section": 4, "type": "Trap", "question": "Which call throws NumberFormatException?", "options": ["Integer.parseInt(\" 12\")", "Integer.parseInt(\"+12\")", "Integer.parseInt(\"-0\")", "Double.parseDouble(\" 3.5 \")"], "answer": 0, "explanation": "Integer.parseInt does not accept spaces; \"+12\" and \"-0\" are valid; Double.parseDouble trims whitespace."}, {"id": 79, "section": 4, "type": "Output", "question": "What is the output of the following code?\n\nStringBuilder sb = new StringBuilder(\"Java\");\nsb.insert(2, \"--\").delete(0, 1).replace(0, 1, \"X\").append(1);\nSystem.out.println(sb);", "options": ["X--va1", "X-va1", "a--va1", "XJ--va1"], "answer": 0, "explanation": "\"Ja--va\" → \"a--va\" → \"X--va\" → \"X--va1\"."}, {"id": 80, "section": 4, "type": "Scenario", "question": "Several threads append log lines to one shared text buffer. Which class is the safest choice?", "options": ["String", "StringBuilder", "StringBuffer", "Character[]"], "answer": 2, "explanation": "StringBuffer's methods are synchronized."}, {"id": 81, "section": 4, "type": "Trap", "question": "What is the output of the following code?\n\nString s = null;\ns += \"a\";\nSystem.out.println(s);", "options": ["a", "nulla", "NullPointerException", "null"], "answer": 1, "explanation": "null + \"a\" gives \"nulla\" (String.valueOf(null reference))."}, {"id": 82, "section": 4, "type": "Concept", "question": "For \"Aa\" and \"BB\", which is true?", "options": ["hashCode() values are the same but equals() is false", "hashCode() values differ", "equals() is true", "== is true"], "answer": 0, "explanation": "Both hash to 2112: a classic collision."}, {"id": 83, "section": 5, "type": "Output", "question": "What is the output of the following code?\n\nenum Level {\n  LOW(1), HIGH(3);\n  private final int v;\n  Level(int v) { this.v = v; }\n  int v() { return v; }\n}\nSystem.out.println(Level.HIGH.v() + Level.HIGH.ordinal());", "options": ["3", "4", "31", "Compile-time error"], "answer": 1, "explanation": "3 + ordinal 1 = 4."}, {"id": 84, "section": 5, "type": "Scenario", "question": "A form sends the department as text \"hr\" and the code calls Dept.valueOf(\"hr\") where the enum constant is HR. What happens?", "options": ["Returns null", "Returns Dept.HR", "Throws IllegalArgumentException", "Throws NullPointerException"], "answer": 2, "explanation": "valueOf is case-sensitive and throws IllegalArgumentException when no constant matches."}, {"id": 85, "section": 5, "type": "Concept", "question": "Which statement about enums is FALSE?", "options": ["An enum can implement an interface", "An enum constructor can be declared public", "Enum constants can have constant-specific class bodies", "Every enum implicitly extends java.lang.Enum"], "answer": 1, "explanation": "Enum constructors are implicitly private; public is not allowed."}, {"id": 86, "section": 5, "type": "Trap", "question": "What happens with the following enum switch expression?\n\nenum Dept { HR, IT, FIN }\nString r = switch (d) {\n  case HR -> \"h\";\n  case IT -> \"i\";\n  case FIN -> \"f\";\n};", "options": ["Compiles: a switch expression over an enum is exhaustive when all constants are covered", "Compile-time error: default is mandatory", "Compile-time error: break is mandatory", "Runtime error"], "answer": 0, "explanation": "Covering every constant makes a switch expression exhaustive without default."}, {"id": 87, "section": 5, "type": "Trap", "question": "What happens with the following code?\n\nfinal int[] arr = {1, 2};\narr[0] = 9; // line 1\narr = new int[3]; // line 2", "options": ["Only line 1 fails", "Only line 2 fails", "Both fail", "Neither fails"], "answer": 1, "explanation": "final fixes the reference, not the array's contents."}, {"id": 88, "section": 5, "type": "Concept", "question": "Which declaration causes a compile-time error?", "options": ["A final class that contains a static method", "abstract final class X {}", "A final method inside an abstract class", "A static final variable"], "answer": 1, "explanation": "abstract and final contradict each other."}, {"id": 89, "section": 5, "type": "Output", "question": "What happens with the following code?\n\nsealed interface Shape permits Circle, Square {}\nrecord Circle(double r) implements Shape {}\nrecord Square(double s) implements Shape {}\nfinal class Triangle implements Shape {}", "options": ["Compiles", "Compile-time error: Triangle is not listed in permits", "Runtime error", "Warning only"], "answer": 1, "explanation": "Only classes listed in permits may implement a sealed type."}, {"id": 90, "section": 5, "type": "Trap", "question": "'sealed class Shape permits Sq {}' and then 'class Sq extends Shape {}'. What is the result?", "options": ["Compiles; Sq is implicitly final", "Compile-time error: Sq must be final, sealed or non-sealed", "Compiles; Sq is implicitly non-sealed", "Runtime error"], "answer": 1, "explanation": "A permitted subclass must be final, sealed or non-sealed (records and enums are implicitly final)."}, {"id": 91, "section": 5, "type": "Output", "question": "What is the output of the following code?\n\nstatic void p(Object o) {\n  if (!(o instanceof Integer i)) { return; }\n  System.out.println(i + 1);\n}\n// main\np(5);", "options": ["6", "Compile-time error: i is not in scope", "51", "ClassCastException"], "answer": 0, "explanation": "Flow scoping: i is in scope after the early return."}, {"id": 92, "section": 5, "type": "Output", "question": "What is the output of the following code?\n\nclass Outer {\n  int x = 10;\n  class Inner {\n    int x = 20;\n    void p() { int x = 30; System.out.println(x + \" \" + this.x + \" \" + Outer.this.x); }\n  }\n}\nnew Outer().new Inner().p();", "options": ["30 20 10", "10 20 30", "30 30 30", "Compile-time error"], "answer": 0, "explanation": "Local x = 30, this.x = 20, Outer.this.x = 10."}, {"id": 93, "section": 5, "type": "Concept", "question": "Which correctly creates an object of a regular (non-static) inner class Inner of Outer from main?", "options": ["Outer.Inner i = new Outer.Inner();", "Inner i = new Inner();", "Outer.Inner i = new Outer().new Inner();", "Inner i = Inner.new Outer();"], "answer": 2, "explanation": "An inner class needs an enclosing instance."}, {"id": 94, "section": 5, "type": "Scenario", "question": "What happens with the following code?\n\nint count = 0;\nRunnable r = new Runnable() {\n  public void run() { count++; }\n};", "options": ["Works; count becomes 1 after run()", "Compile-time error: variable captured by an anonymous class must be effectively final", "Runtime exception", "Prints 0"], "answer": 1, "explanation": "Captured locals must be final or effectively final."}, {"id": 95, "section": 6, "type": "Output", "question": "What is the output of the following code?\n\nabstract class Device {\n  Device() { System.out.print(\"D \"); }\n  abstract void on();\n}\nclass Phone extends Device {\n  Phone() { System.out.print(\"P \"); }\n  void on() { }\n}\nnew Phone();", "options": ["P D", "D P", "P", "D"], "answer": 1, "explanation": "An abstract class has a constructor; it runs first via super()."}, {"id": 96, "section": 6, "type": "Concept", "question": "Which declaration is valid?", "options": ["An abstract method with a body", "private abstract void f();", "An abstract class with no abstract methods", "abstract static void f();"], "answer": 2, "explanation": "An abstract class may have zero abstract methods. Abstract methods cannot have a body, be private or static."}, {"id": 97, "section": 6, "type": "Trap", "question": "What happens with the following code?\n\ninterface I { int X = 5; }\nclass C implements I { void f() { X = 6; } }", "options": ["Compiles; X becomes 6", "Compile-time error: cannot assign to a final variable", "Runtime error", "Prints 5"], "answer": 1, "explanation": "Interface fields are public static final."}, {"id": 98, "section": 6, "type": "Trap", "question": "What happens with the following code?\n\ninterface I { default void hi() { System.out.print(\"I\"); } }\ninterface J { default void hi() { System.out.print(\"J\"); } }\nclass C implements I, J { }", "options": ["Compiles; prints I when called", "Compiles; prints J when called", "Compile-time error: C inherits unrelated defaults for hi()", "Runtime ambiguity"], "answer": 2, "explanation": "You must override hi() in C (and may call I.super.hi())."}, {"id": 99, "section": 6, "type": "Output", "question": "What is the output of the following code?\n\ninterface I { default void hi() { System.out.print(\"I\"); } }\nclass P { public void hi() { System.out.print(\"P\"); } }\nclass C extends P implements I { }\nnew C().hi();", "options": ["I", "P", "IP", "Compile-time error"], "answer": 1, "explanation": "The class wins rule: a concrete class method beats an interface default."}, {"id": 100, "section": 6, "type": "Trap", "question": "'interface I { static void util() { } }' and 'class C implements I { }'. Which call compiles?", "options": ["new C().util();", "C.util();", "I.util();", "None of them"], "answer": 2, "explanation": "Static interface methods are called only through the interface name."}, {"id": 101, "section": 6, "type": "Concept", "question": "Which can be declared inside an interface in Java 17?", "options": ["A private method with a body", "A protected method", "An instance field", "A constructor"], "answer": 0, "explanation": "Private methods are allowed since Java 9. Members are public (or private), fields are constants, no constructors."}, {"id": 102, "section": 6, "type": "Concept", "question": "Which interface qualifies as a functional interface?", "options": ["Two abstract methods", "One abstract method, one default method, and a re-declaration of boolean equals(Object o)", "No abstract methods", "Two unrelated abstract methods and one static method"], "answer": 1, "explanation": "Methods matching public Object methods don't count as abstract; default and static methods don't count either."}, {"id": 103, "section": 6, "type": "Scenario", "question": "In a Smart Device system, a Phone and an ElectricCar (unrelated hierarchies) can both be charged. How should Rechargeable be modeled?", "options": ["Abstract class, since all devices charge", "Interface, since it is a capability shared by unrelated classes", "Final class", "Enum"], "answer": 1, "explanation": "Capabilities across unrelated classes are modeled with interfaces; shared state and partial implementation suit an abstract class."}, {"id": 104, "section": 6, "type": "Concept", "question": "Which compiles?", "options": ["class X extends A, B (A and B are classes)", "interface Z extends I, J", "class Y implements A (A is a class)", "interface W implements I"], "answer": 1, "explanation": "Interfaces can extend multiple interfaces."}, {"id": 105, "section": 6, "type": "Trap", "question": "What happens with the following code?\n\ninterface I { void a(); void b(); }\nabstract class P implements I { public void a() { } }\nclass C extends P { public void a() { } }", "options": ["Compiles", "Compile-time error: C must implement b()", "Compile-time error: P must implement b()", "Compile-time error: a() cannot be redefined"], "answer": 1, "explanation": "P is abstract so it can skip b(), but the concrete class C must implement it."}, {"id": 106, "section": 6, "type": "Scenario", "question": "How many objects are eligible for GC after the last line?\n\nObject a = new Object(); // O1\nObject b = new Object(); // O2\nObject c = a;\na = null;\nb = c;\nc = null;", "options": ["0", "1", "2", "3"], "answer": 1, "explanation": "O1 is still reachable via b; only O2 is eligible."}, {"id": 107, "section": 6, "type": "Trap", "question": "What happens after the following code?\n\nclass Node { Node next; }\nNode n1 = new Node(), n2 = new Node();\nn1.next = n2;\nn2.next = n1;\nn1 = null;\nn2 = null;", "options": ["Neither is eligible because they reference each other", "Both are eligible (island of isolation)", "Only n1's object is eligible", "Only n2's object is eligible"], "answer": 1, "explanation": "Unreachable from any live root, so both are eligible."}, {"id": 108, "section": 6, "type": "Concept", "question": "System.gc() does what?", "options": ["Guarantees immediate garbage collection", "Suggests (requests) that the JVM run garbage collection", "Forces finalize() on all objects", "Clears the stack"], "answer": 1, "explanation": "It is only a request."}, {"id": 109, "section": 6, "type": "Concept", "question": "Which statement about finalize() is correct?", "options": ["It is guaranteed to run before the program exits", "The JVM calls it at most once per object", "It is called every time GC runs", "It is called on local variables when a method ends"], "answer": 1, "explanation": "At most once (and finalize() is deprecated)."}, {"id": 110, "section": 6, "type": "Scenario", "question": "Which situation can cause a memory leak in Java despite garbage collection?", "options": ["Local variables inside a method", "A static collection that keeps references to objects that are never removed", "Setting a reference to null", "Calling System.gc()"], "answer": 1, "explanation": "Reachable but unused objects are never collected."}, {"id": 111, "section": 7, "type": "Output", "question": "What is the output of the following code?\n\nstatic int f() {\n  try { return 1; } finally { System.out.print(\"F \"); }\n}\nSystem.out.println(f());", "options": ["1 F", "F 1", "1", "F"], "answer": 1, "explanation": "finally runs (prints F) before the method returns; then println prints 1."}, {"id": 112, "section": 7, "type": "Trap", "question": "What is the output of the following code?\n\nstatic int g() {\n  int x = 1;\n  try { return x; } finally { x = 2; }\n}\nSystem.out.println(g());", "options": ["1", "2", "3", "Compile-time error"], "answer": 0, "explanation": "The return value is saved before finally runs; changing x later does not affect it."}, {"id": 113, "section": 7, "type": "Trap", "question": "What happens with the following code?\n\ntry { int[] a = new int[2]; a[2] = 1; }\ncatch (Exception e) { System.out.print(\"E \"); }\ncatch (ArrayIndexOutOfBoundsException e) { System.out.print(\"A \"); }", "options": ["E", "A", "Compile-time error: exception already caught", "Runtime error"], "answer": 2, "explanation": "A subclass catch after its superclass catch is unreachable."}, {"id": 114, "section": 7, "type": "Trap", "question": "What is wrong with 'catch (IOException | FileNotFoundException e)'?", "options": ["Nothing, it compiles", "Compile-time error: alternatives in a multi-catch cannot be related by subclassing", "Runtime error", "e becomes non-final"], "answer": 1, "explanation": "Multi-catch alternatives cannot be subclass-related."}, {"id": 115, "section": 7, "type": "Output", "question": "What is the output of the following code?\n\nstatic void a() { try { b(); } finally { System.out.print(\"A \"); } }\nstatic void b() { throw new RuntimeException(\"x\"); }\n// main\ntry { a(); } catch (Exception e) { System.out.print(\"M \"); }", "options": ["M A", "A M", "M", "A"], "answer": 1, "explanation": "finally in a() runs while the exception propagates, then main catches."}, {"id": 116, "section": 7, "type": "Trap", "question": "Which of these is a CHECKED exception?", "options": ["IllegalStateException", "ArrayStoreException", "InterruptedException", "NumberFormatException"], "answer": 2, "explanation": "InterruptedException is checked. The others are RuntimeExceptions."}, {"id": 117, "section": 7, "type": "Scenario", "question": "Banking code:\nclass InsufficientBalanceException extends Exception { }\nvoid withdraw(double amt) {\n  if (amt > bal) throw new InsufficientBalanceException();\n}\nWhat happens?", "options": ["Compiles and works", "Compile-time error: unreported checked exception", "Runtime error", "Only a warning"], "answer": 1, "explanation": "Must handle or declare with throws."}, {"id": 118, "section": 7, "type": "Output", "question": "What is the output of the following code?\n\nclass R implements AutoCloseable {\n  String n;\n  R(String n) { this.n = n; System.out.print(\"open\" + n + \" \"); }\n  public void close() { System.out.print(\"close\" + n + \" \"); }\n}\ntry (R a = new R(\"1\"); R b = new R(\"2\")) { System.out.print(\"body \"); }", "options": ["open1 open2 body close1 close2", "open1 open2 body close2 close1", "open1 body open2 close2 close1", "open1 open2 close2 close1 body"], "answer": 1, "explanation": "Resources close in reverse order after the body."}, {"id": 119, "section": 7, "type": "Trap", "question": "What exception reaches the caller?\n\ntry { throw new RuntimeException(\"try\"); }\nfinally { throw new IllegalStateException(\"fin\"); }", "options": ["RuntimeException(\"try\")", "IllegalStateException(\"fin\")", "Both, chained", "None"], "answer": 1, "explanation": "The exception thrown in finally replaces the earlier one."}, {"id": 120, "section": 7, "type": "Output", "question": "What is the output of the following code?\n\ntry { System.out.print(\"1 \"); int x = 5 / 0; System.out.print(\"2 \"); }\ncatch (ArithmeticException e) { System.out.print(\"3 \"); }\nfinally { System.out.print(\"4 \"); }\nSystem.out.print(\"5\");", "options": ["1 2 4 5", "1 3 4 5", "1 3 5", "1 4 5"], "answer": 1, "explanation": "1 → exception → catch prints 3 → finally 4 → 5."}, {"id": 121, "section": 7, "type": "Trap", "question": "What is the output of the following code?\n\ntry { System.exit(0); }\nfinally { System.out.print(\"F\"); }", "options": ["F", "Prints nothing", "Throws an exception", "Compile-time error"], "answer": 1, "explanation": "System.exit halts the JVM; finally does not run."}, {"id": 122, "section": 7, "type": "Scenario", "question": "A method recurses infinitely inside 'try { ... } catch (Exception e) { log(e); }'. What happens?", "options": ["The exception is caught and logged", "The program terminates with an uncaught StackOverflowError", "Compile-time error", "It returns normally"], "answer": 1, "explanation": "StackOverflowError is an Error, not an Exception."}, {"id": 123, "section": 7, "type": "Trap", "question": "What happens with the following code?\n\nthrow new RuntimeException();\nSystem.out.println(\"x\");", "options": ["Prints x then throws", "Throws only", "Compile-time error: unreachable statement", "Warning only"], "answer": 2, "explanation": "Code after an unconditional throw is unreachable."}, {"id": 124, "section": 7, "type": "Trap", "question": "What happens with the following code?\n\ninterface Rd { void read() throws IOException; }\nclass R implements Rd { public void read() { } }\nR r = new R(); r.read(); // call 1, no try\nRd q = new R(); q.read(); // call 2, no try", "options": ["Only call 1 fails", "Only call 2 fails", "Both fail", "Neither fails"], "answer": 1, "explanation": "The reference type decides: Rd declares IOException, R does not."}, {"id": 125, "section": 7, "type": "Concept", "question": "Which compiles?", "options": ["try { }", "try { } finally { }", "try { } catch", "catch (Exception e) { } alone"], "answer": 1, "explanation": "try needs a catch, finally or resources."}, {"id": 126, "section": 7, "type": "Scenario", "question": "A banking app parses an account number with Integer.parseInt(\"abc\"). Which is true?", "options": ["NumberFormatException extends IllegalArgumentException, so catch (IllegalArgumentException e) handles it", "NumberFormatException extends IOException", "NumberFormatException is a checked exception", "NumberFormatException extends Error"], "answer": 0, "explanation": "NumberFormatException is an unchecked subclass of IllegalArgumentException."}, {"id": 127, "section": 8, "type": "Output", "question": "What is the output after serialize/deserialize?\n\nclass U implements Serializable {\n  String name = \"Ann\";\n  transient String pwd = \"123\";\n}\n// serialize a U object to a file, then deserialize it into u2\nSystem.out.println(u2.name + \" \" + u2.pwd);", "options": ["Ann null", "Ann 123", "null null", "NotSerializableException"], "answer": 0, "explanation": "transient fields are skipped and get default values."}, {"id": 128, "section": 8, "type": "Scenario", "question": "Employee implements Serializable has a field Address addr, but Address does not implement Serializable. What happens on writeObject(emp)?", "options": ["Works; addr is skipped", "NotSerializableException at runtime", "Compile-time error", "addr silently becomes null"], "answer": 1, "explanation": "Every non-transient object field must be serializable."}, {"id": 129, "section": 8, "type": "Trap", "question": "class P { P() { System.out.print(\"P \"); } }\nclass C extends P implements Serializable { C() { System.out.print(\"C \"); } }\nWhat is printed while DESERIALIZING a C object (not while creating it)?", "options": ["P C", "C", "P", "Nothing"], "answer": 2, "explanation": "On deserialization, constructors of serializable classes are skipped; the first non-serializable superclass's no-arg constructor runs."}, {"id": 130, "section": 8, "type": "Scenario", "question": "A logging program uses new FileWriter(\"log.txt\") and every run erases the old log lines. Why?", "options": ["The writer was opened without the append flag, so it truncates the file", "flush() was not called", "The file is locked", "Wrong charset"], "answer": 0, "explanation": "Use new FileWriter(name, true) to append."}, {"id": 131, "section": 8, "type": "Concept", "question": "Best class for copying a binary file such as a JPEG?", "options": ["FileReader", "FileInputStream (byte stream)", "BufferedReader", "Scanner"], "answer": 1, "explanation": "Byte streams for binary data; Readers/Writers are for text."}, {"id": 132, "section": 8, "type": "Scenario", "question": "A program writes 100 lines using a BufferedWriter and then ends without calling flush() or close(). What is the likely result?", "options": ["All data is always on disk", "Part or all of the buffered data may never be written", "Compile-time error", "NullPointerException"], "answer": 1, "explanation": "Buffered data must be flushed or closed."}, {"id": 133, "section": 8, "type": "Trap", "question": "What is the output of the following code?\n\nclass P {\n  int id; P(int id) { this.id = id; }\n  public boolean equals(P o) { return id == o.id; }\n}\nList<P> l = List.of(new P(1));\nSystem.out.println(l.contains(new P(1)));", "options": ["true", "false", "Compile-time error", "NullPointerException"], "answer": 1, "explanation": "equals(P) overloads rather than overrides equals(Object); contains() uses equals(Object)."}, {"id": 134, "section": 8, "type": "Concept", "question": "Which statement about the equals()/hashCode() contract is correct?", "options": ["If a.equals(b) is true, then a.hashCode() must equal b.hashCode()", "If two hash codes are equal, the objects must be equal", "hashCode() must return a unique value per object", "hashCode() must return a random value"], "answer": 0, "explanation": "Equal objects need equal hash codes; the reverse is not required."}, {"id": 135, "section": 8, "type": "Output", "question": "What is the output of the following code?\n\nLocalDate d = LocalDate.of(2024, 1, 31);\nSystem.out.println(d.plusMonths(1));", "options": ["2024-02-31", "2024-02-29", "2024-03-02", "DateTimeException"], "answer": 1, "explanation": "The day is clamped to the last valid day of February (leap year)."}, {"id": 136, "section": 8, "type": "Trap", "question": "What is the result of the following code?\n\nLocalDate d = LocalDate.parse(\"2026-1-5\");", "options": ["2026-01-05", "DateTimeParseException", "null", "2026-1-5"], "answer": 1, "explanation": "ISO format needs zero-padded month and day."}, {"id": 137, "section": 9, "type": "Trap", "question": "What happens with the following code?\n\nList<Object> lo = new ArrayList<String>();", "options": ["Compiles", "Compile-time error: generics are invariant", "Runtime ClassCastException", "Compiles with a warning"], "answer": 1, "explanation": "List<String> is not a List<Object>."}, {"id": 138, "section": 9, "type": "Trap", "question": "What happens with the following code?\n\nList<? extends Number> l = new ArrayList<Integer>();\nl.add(5);", "options": ["Compiles and adds 5", "Compile-time error", "Runtime error", "Adds null"], "answer": 1, "explanation": "With ? extends, the list is read-only (only null can be added)."}, {"id": 139, "section": 9, "type": "Trap", "question": "What happens with the following code?\n\nList<? super Integer> l = new ArrayList<Number>();\nl.add(5); // line 1\nInteger x = l.get(0); // line 2", "options": ["Line 1 fails", "Line 2 fails", "Both fail", "Neither fails"], "answer": 1, "explanation": "? super Integer allows add(Integer), but get() returns Object."}, {"id": 140, "section": 9, "type": "Output", "question": "What is the output of the following code?\n\nstatic <T extends Comparable<T>> T max(T a, T b) { return a.compareTo(b) > 0 ? a : b; }\nSystem.out.println(max(\"apple\", \"banana\") + max(3, 7));", "options": ["banana7", "apple3", "Compile-time error", "banana10"], "answer": 0, "explanation": "\"banana\" + 7 = \"banana7\"."}, {"id": 141, "section": 9, "type": "Trap", "question": "What is the output of the following code?\n\nList<String> a = new ArrayList<>();\nList<Integer> b = new ArrayList<>();\nSystem.out.println(a.getClass() == b.getClass());", "options": ["true", "false", "Compile-time error", "ClassCastException"], "answer": 0, "explanation": "Type erasure: both are ArrayList at runtime."}, {"id": 142, "section": 9, "type": "Trap", "question": "In one class: 'void f(List<String> l)' and 'void f(List<Integer> l)'. Result?", "options": ["Valid overloading", "Compile-time error: same erasure", "Runtime error", "Only a warning"], "answer": 1, "explanation": "Both erase to f(List)."}, {"id": 143, "section": 9, "type": "Concept", "question": "In class Box<T> { ... }, which line is illegal?", "options": ["private T value;", "public T get() { return value; }", "static T shared;", "<U> void m(U u) { }"], "answer": 2, "explanation": "Static members cannot use the class type parameter."}, {"id": 144, "section": 9, "type": "Output", "question": "What is the output of the following code?\n\nList<Integer> l = new ArrayList<>(List.of(10, 20, 30, 1));\nl.remove(1);\nl.remove(Integer.valueOf(1));\nSystem.out.println(l);", "options": ["[10, 30]", "[10, 20, 30]", "[20, 30]", "[10, 30, 1]"], "answer": 0, "explanation": "remove(1) removes index 1 (20); remove(Integer) removes the value 1."}, {"id": 145, "section": 9, "type": "Trap", "question": "What is the output of the following code?\n\nList<Integer> l = new ArrayList<>(List.of(1, 2, 3, 4));\nfor (Integer x : l) { if (x == 3) l.remove(x); }\nSystem.out.println(l);", "options": ["ConcurrentModificationException", "[1, 2, 4] with no exception", "[1, 2, 3]", "IndexOutOfBoundsException"], "answer": 1, "explanation": "Removing the second-last element ends the loop before the fail-fast check (a classic trap)."}, {"id": 146, "section": 9, "type": "Trap", "question": "What happens with the following code?\n\nList<Integer> l = Arrays.asList(1, 2, 3);\nl.set(0, 9);\nl.add(4);", "options": ["Both work", "set works; add throws UnsupportedOperationException", "set throws; add works", "Both throw"], "answer": 1, "explanation": "Arrays.asList is a fixed-size list backed by the array."}, {"id": 147, "section": 9, "type": "Scenario", "question": "A Task Manager adds tasks at the end and mostly reads a task by index (get(i)) in loops. Best List?", "options": ["ArrayList", "LinkedList", "Both are identical", "Vector only"], "answer": 0, "explanation": "ArrayList gives O(1) get(i); LinkedList is O(n)."}, {"id": 148, "section": 9, "type": "Concept", "question": "Which statement is TRUE?", "options": ["ArrayList methods are synchronized", "Vector methods are synchronized", "HashMap is synchronized", "LinkedList is synchronized"], "answer": 1, "explanation": "Vector is a legacy synchronized list."}, {"id": 149, "section": 9, "type": "Output", "question": "What is the output of the following code?\n\nclass E {\n  int id; String n;\n  E(int id, String n) { this.id = id; this.n = n; }\n  public boolean equals(Object o) { return o instanceof E e && e.id == id; }\n  public int hashCode() { return Integer.hashCode(id); }\n}\nSet<E> s = new HashSet<>();\ns.add(new E(1, \"A\")); s.add(new E(1, \"B\")); s.add(new E(2, \"A\"));\nSystem.out.println(s.size());", "options": ["1", "2", "3", "4"], "answer": 1, "explanation": "id 1 duplicates; set = {E1, E2}."}, {"id": 150, "section": 9, "type": "Trap", "question": "Same class E as Q149 but only equals() is overridden (no hashCode()). What is s.size() after adding two new E(1, \"A\") objects to a HashSet?", "options": ["Always 1", "Typically 2", "Exception", "Compile-time error"], "answer": 1, "explanation": "Without hashCode() the identity hashes usually differ, so both are stored (a contract violation)."}, {"id": 151, "section": 9, "type": "Trap", "question": "What is the output of the following code?\n\nMap<E, String> m = new HashMap<>();\nE k = new E(1, \"A\");\nm.put(k, \"v\");\nk.id = 2;\nSystem.out.println(m.get(k));", "options": ["v", "null", "Exception", "Compile-time error"], "answer": 1, "explanation": "The hash changed after insertion; lookup goes to a different bucket."}, {"id": 152, "section": 9, "type": "Output", "question": "What is the output of the following code?\n\nMap<String, Integer> m = new HashMap<>();\nSystem.out.print(m.put(\"a\", 1) + \" \");\nSystem.out.print(m.put(\"a\", 2) + \" \");\nSystem.out.print(m.put(null, 3) + \" \");\nSystem.out.print(m.get(null));", "options": ["null 1 null 3", "1 2 3 3", "null null null 3", "NullPointerException"], "answer": 0, "explanation": "put returns the previous value; HashMap allows one null key."}, {"id": 153, "section": 9, "type": "Trap", "question": "What happens with the following code?\n\nMap<String, Integer> m = new TreeMap<>();\nm.put(\"b\", 1);\nm.put(\"a\", 2);\nm.put(null, 3);", "options": ["Works; null sorts first", "NullPointerException", "ClassCastException", "Compile-time error"], "answer": 1, "explanation": "TreeMap with natural ordering cannot compare null."}, {"id": 154, "section": 9, "type": "Output", "question": "What is the output of the following code?\n\nSet<String> s = new TreeSet<>(List.of(\"pear\", \"apple\", \"fig\"));\nSystem.out.println(s);", "options": ["[pear, apple, fig]", "[apple, fig, pear]", "[fig, apple, pear]", "Order is unpredictable"], "answer": 1, "explanation": "TreeSet sorts naturally."}, {"id": 155, "section": 9, "type": "Scenario", "question": "TreeSet<Student> ts = new TreeSet<>(); ts.add(new Student(1)); where Student does not implement Comparable and no Comparator is given. What happens?", "options": ["Compile-time error", "ClassCastException at runtime on add", "Works; insertion order is kept", "NullPointerException"], "answer": 1, "explanation": "TreeSet casts to Comparable when adding."}, {"id": 156, "section": 9, "type": "Trap", "question": "What is the output of the following code?\n\nSet<String> s = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);\ns.add(\"Java\"); s.add(\"JAVA\"); s.add(\"java\");\nSystem.out.println(s.size() + \" \" + s);", "options": ["3 [JAVA, Java, java]", "1 [Java]", "1 [java]", "3 [Java, JAVA, java]"], "answer": 1, "explanation": "TreeSet uses the comparator for uniqueness; the first inserted element stays."}, {"id": 157, "section": 9, "type": "Concept", "question": "A default new HashMap<>() (capacity 16, load factor 0.75). On which put() does the first resize happen?", "options": ["12th", "13th", "16th", "17th"], "answer": 1, "explanation": "Threshold is 12; the resize happens when the size exceeds it (13th entry)."}, {"id": 158, "section": 9, "type": "Concept", "question": "In Java 8+, a HashMap bucket's linked list is converted to a red-black tree when:", "options": ["It has at least 8 nodes and the table capacity is at least 64", "It has 4 nodes", "It has 16 nodes regardless of capacity", "Any collision occurs"], "answer": 0, "explanation": "Treeification needs chain length of 8 or more and capacity of 64 or more; otherwise the table resizes."}, {"id": 159, "section": 9, "type": "Output", "question": "What is the output of the following code?\n\nSet<String> s = new HashSet<>();\ns.add(\"Aa\"); s.add(\"BB\");\nSystem.out.println(s.size());", "options": ["1", "2", "Exception", "0"], "answer": 1, "explanation": "\"Aa\" and \"BB\" collide in hashCode but are unequal, so both are stored."}, {"id": 160, "section": 9, "type": "Concept", "question": "Which statement is TRUE?", "options": ["HashMap and Hashtable both allow null keys", "Hashtable does not allow null keys or values", "TreeMap allows many null keys", "LinkedHashMap does not allow null values"], "answer": 1, "explanation": "Hashtable rejects nulls; HashMap allows one null key; TreeMap (natural) allows none."}, {"id": 161, "section": 9, "type": "Trap", "question": "What is the output of the following code?\n\nList<String> base = new ArrayList<>(List.of(\"a\"));\nList<String> ro = Collections.unmodifiableList(base);\nbase.add(\"b\");\nSystem.out.println(ro);", "options": ["[a]", "[a, b]", "UnsupportedOperationException", "[]"], "answer": 1, "explanation": "unmodifiableList is a read-only view of the original list, not a copy."}, {"id": 162, "section": 9, "type": "Output", "question": "Students: Ravi(IT,85), Anu(CS,90), Sam(CS,95), Tej(IT,90). Sorted by dept asc, then marks desc. What order?\n\nlist.sort(Comparator.comparing(S::dept).thenComparing(S::marks, Comparator.reverseOrder()));", "options": ["Sam Anu Tej Ravi", "Anu Sam Ravi Tej", "Sam Anu Ravi Tej", "Anu Sam Tej Ravi"], "answer": 0, "explanation": "CS: Sam 95, Anu 90; then IT: Tej 90, Ravi 85."}, {"id": 163, "section": 9, "type": "Trap", "question": "What is the output of the following code?\n\nComparator<Integer> c = (a, b) -> a - b;\nSystem.out.println(c.compare(Integer.MIN_VALUE, 1));", "options": ["A negative number", "2147483647 (a wrong positive result due to overflow)", "0", "ArithmeticException"], "answer": 1, "explanation": "MIN_VALUE - 1 overflows to MAX_VALUE. Use Integer.compare(a, b)."}, {"id": 164, "section": 9, "type": "Output", "question": "What is the output of the following code?\n\nQueue<Integer> pq = new PriorityQueue<>(List.of(5, 1, 4, 2));\nSystem.out.println(pq.poll() + \" \" + pq.peek());", "options": ["5 1", "1 2", "1 4", "2 1"], "answer": 1, "explanation": "The min-heap polls 1; the next head is 2."}, {"id": 165, "section": 10, "type": "Concept", "question": "Which lambda is INVALID for Function<Integer,Integer>?", "options": ["x -> x * 2", "(x) -> { return x * 2; }", "x -> { x * 2; }", "(Integer x) -> x * 2"], "answer": 2, "explanation": "A block lambda needs a return statement; x * 2; is not a valid statement."}, {"id": 166, "section": 10, "type": "Trap", "question": "What happens with the following code?\n\nint base = 10;\nFunction<Integer, Integer> f = x -> x + base;\nbase = 20;", "options": ["Works; f.apply(1) gives 21", "Compile-time error: base must be effectively final", "f.apply(1) gives 11", "Runtime error"], "answer": 1, "explanation": "Captured locals must be effectively final; reassigning breaks that."}, {"id": 167, "section": 10, "type": "Output", "question": "What is the output of the following code?\n\nPredicate<String> p1 = s -> s.length() > 3;\nPredicate<String> p2 = s -> s.startsWith(\"a\");\nSystem.out.print(p1.and(p2).test(\"apple\") + \" \" + p1.negate().or(p2).test(\"beet\"));", "options": ["true true", "true false", "false true", "false false"], "answer": 1, "explanation": "\"apple\": true and true gives true. \"beet\": negate(len>3) is false, startsWith(a) is false, so false."}, {"id": 168, "section": 10, "type": "Output", "question": "What is the output of the following code?\n\nFunction<Integer, Integer> d = x -> x * 2;\nFunction<Integer, Integer> a = x -> x + 3;\nSystem.out.print(d.andThen(a).apply(5) + \" \" + d.compose(a).apply(5));", "options": ["13 16", "16 13", "13 13", "16 16"], "answer": 0, "explanation": "andThen: d then a = 10+3 = 13; compose: a then d = (5+3)*2 = 16."}, {"id": 169, "section": 10, "type": "Scenario", "question": "() -> LocalDate.now() fits which built-in functional interface?", "options": ["Consumer<LocalDate>", "Supplier<LocalDate>", "Function<LocalDate,LocalDate>", "Predicate<LocalDate>"], "answer": 1, "explanation": "No arguments and returns a value: Supplier."}, {"id": 170, "section": 10, "type": "Concept", "question": "System.out::println used as a Consumer is which kind of method reference?", "options": ["Static method reference", "Instance method reference of a particular (bound) object", "Instance method reference of an arbitrary object of a type", "Constructor reference"], "answer": 1, "explanation": "It is bound to the System.out object."}, {"id": 171, "section": 10, "type": "Output", "question": "What is printed by the following stream pipeline?\n\nOptional<Integer> r = Stream.of(1, 2, 3, 4)\n  .filter(x -> { System.out.print(\"f\" + x + \" \"); return x % 2 == 0; })\n  .map(x -> { System.out.print(\"m\" + x + \" \"); return x * x; })\n  .findFirst();", "options": ["f1 f2 f3 f4 m2 m4", "f1 f2 m2", "m2 f1 f2", "Nothing"], "answer": 1, "explanation": "Streams process element by element and findFirst short-circuits."}, {"id": 172, "section": 10, "type": "Trap", "question": "What is printed by the following stream pipeline?\n\nStream.of(1, 2, 3, 4)\n  .filter(x -> { System.out.print(\"f\" + x + \" \"); return x % 2 == 0; })\n  .map(x -> x * x);", "options": ["f1 f2 f3 f4", "Nothing is printed (no terminal operation)", "f1 f2", "Compile-time error"], "answer": 1, "explanation": "Intermediate operations are lazy."}, {"id": 173, "section": 10, "type": "Trap", "question": "What is the output of the following code?\n\nStream<Integer> s = List.of(1, 2, 3).stream();\ns.forEach(System.out::print);\ns.forEach(System.out::print);", "options": ["123123", "123 and then IllegalStateException", "Compile-time error", "123 then NullPointerException"], "answer": 1, "explanation": "A stream can be consumed only once."}, {"id": 174, "section": 10, "type": "Output", "question": "What is the output of the following code?\n\nList<String> r = Stream.of(\"a\", \"bb\", \"cc\", \"ddd\")\n  .filter(s -> s.length() > 1)\n  .map(String::toUpperCase)\n  .collect(Collectors.toList());\nSystem.out.println(r);", "options": ["[BB, CC, DDD]", "[A, BB, CC, DDD]", "[bb, cc, ddd]", "[BB, CC]"], "answer": 0, "explanation": "Filter keeps length > 1; map uppercases."}, {"id": 175, "section": 10, "type": "Output", "question": "What is the output of the following code?\n\nList<List<Integer>> ll = List.of(List.of(1, 2), List.of(3), List.of());\nSystem.out.println(ll.stream().flatMap(List::stream).map(x -> x * 2).reduce(0, Integer::sum));", "options": ["6", "12", "3", "Compile-time error"], "answer": 1, "explanation": "(1+2+3) x 2 = 12."}, {"id": 176, "section": 10, "type": "Trap", "question": "What is the output of the following code?\n\nSystem.out.println(Stream.of(1, 2, 3).reduce(Integer::sum));", "options": ["6", "Optional[6]", "Optional.6", "Compile-time error"], "answer": 1, "explanation": "reduce without identity returns an Optional."}, {"id": 177, "section": 10, "type": "Scenario", "question": "What is the output of the following code?\n\nMap<Integer, List<String>> m = Stream.of(\"a\", \"bb\", \"cc\", \"d\")\n  .collect(Collectors.groupingBy(String::length));\nSystem.out.println(m);", "options": ["{1=[a, d], 2=[bb, cc]}", "{2=[bb, cc], 1=[a, d]}", "{1=[a], 2=[bb, cc]}", "[[a, d], [bb, cc]]"], "answer": 0, "explanation": "groupingBy gives a HashMap; keys 1 and 2 print in that order."}, {"id": 178, "section": 10, "type": "Output", "question": "What is the output of the following code?\n\nSystem.out.println(Stream.of(1, 2, 3, 4, 5)\n  .collect(Collectors.partitioningBy(x -> x % 2 == 0, Collectors.counting())));", "options": ["{false=3, true=2}", "{true=2, false=3}", "{2=true, 3=false}", "{even=2, odd=3}"], "answer": 0, "explanation": "partitioningBy gives false first, then true; counts are 3 and 2."}, {"id": 179, "section": 10, "type": "Output", "question": "What is the output of the following code?\n\nStream.of(5, 3, 5, 1, 3).distinct().sorted().skip(1).limit(1).forEach(System.out::println);", "options": ["1", "3", "5", "3 5"], "answer": 1, "explanation": "[5,3,1] → sorted [1,3,5] → skip 1 → [3,5] → limit 1 → 3."}, {"id": 180, "section": 10, "type": "Trap", "question": "What is the output of the following code? (Java 17)\n\nSystem.out.println(Stream.of(1, 2, 3).peek(x -> System.out.print(x + \" \")).count());", "options": ["1 2 3 3", "3 (peek is not executed because the count is known from the source)", "3 1 2 3", "Compile-time error"], "answer": 1, "explanation": "Since Java 9, count() may skip the pipeline for SIZED sources, so peek() is skipped."}, {"id": 181, "section": 10, "type": "Concept", "question": "Which statement is TRUE?", "options": ["Optional.of(null) throws NullPointerException", "Optional.ofNullable(null).orElse(\"x\") throws an exception", "Optional.empty().get() returns null", "Optional.of(\"a\").isEmpty() is true"], "answer": 0, "explanation": "Optional.of rejects null; get() on empty throws NoSuchElementException."}, {"id": 182, "section": 10, "type": "Concept", "question": "Which statement is TRUE?", "options": ["parallelStream().forEach() preserves encounter order", "forEachOrdered() preserves encounter order even on a parallel stream", "Parallel streams are always faster", "stream() runs on multiple threads by default"], "answer": 1, "explanation": "forEach on a parallel stream has no order guarantee."}, {"id": 183, "section": 11, "type": "Trap", "question": "What is the output of the following code?\n\nThread t = new Thread(() -> System.out.print(Thread.currentThread().getName()));\nt.run();", "options": ["Thread-0", "main", "Nothing", "Exception"], "answer": 1, "explanation": "run() is a normal method call on the main thread; start() creates a new thread."}, {"id": 184, "section": 11, "type": "Trap", "question": "What happens with the following code?\n\nThread t = new Thread(() -> { });\nt.start();\nt.start();", "options": ["Runs twice", "IllegalThreadStateException", "Second call is ignored silently", "Compile-time error"], "answer": 1, "explanation": "A thread can be started only once."}, {"id": 185, "section": 11, "type": "Output", "question": "What is the output of the following code?\n\nThread t = new Thread(() -> System.out.print(\"T \"));\nt.start();\nt.join();\nSystem.out.print(\"M \");", "options": ["T M", "M T", "Either order", "M"], "answer": 0, "explanation": "join() waits for T to finish."}, {"id": 186, "section": 11, "type": "Scenario", "question": "Two threads each execute count++ 1000 times on a shared non-volatile int (no synchronization). The final value is:", "options": ["Always 2000", "At most 2000, and often less (race condition)", "Always 1000", "An exception is thrown"], "answer": 1, "explanation": "count++ is not atomic (read-modify-write); use synchronized or AtomicInteger."}, {"id": 187, "section": 11, "type": "Trap", "question": "Two threads call a synchronized INSTANCE method, but on two DIFFERENT objects. What happens?", "options": ["One blocks the other", "They run concurrently (the lock is per object)", "Deadlock", "Compile-time error"], "answer": 1, "explanation": "Instance locks belong to each object; a static synchronized method locks on the Class object."}, {"id": 188, "section": 11, "type": "Trap", "question": "Calling obj.wait() outside a synchronized block on obj throws:", "options": ["InterruptedException", "IllegalMonitorStateException", "NullPointerException", "Nothing; it just waits"], "answer": 1, "explanation": "wait/notify require owning the object's monitor."}, {"id": 189, "section": 11, "type": "Concept", "question": "Which is correct regarding sleep() and wait()?", "options": ["sleep() releases the lock; wait() does not", "wait() releases the monitor; sleep() does not", "Both release the lock", "Neither releases the lock"], "answer": 1, "explanation": "wait() releases the monitor and sleep() keeps it."}, {"id": 190, "section": 11, "type": "Concept", "question": "Which statement is TRUE?", "options": ["setPriority() guarantees higher-priority threads run first", "yield() guarantees another thread will run", "join() makes the calling thread wait until the target thread finishes", "sleep() releases all locks"], "answer": 2, "explanation": "Priorities and yield are only hints."}, {"id": 191, "section": 11, "type": "Concept", "question": "new ConcurrentHashMap<String,Integer>().put(null, 1) does what?", "options": ["Works", "Throws NullPointerException", "Throws ConcurrentModificationException", "Compile-time error"], "answer": 1, "explanation": "ConcurrentHashMap disallows null keys and values."}, {"id": 192, "section": 11, "type": "Concept", "question": "To invoke a private method secret() of another class using reflection, you need:", "options": ["getMethod(\"secret\") and invoke", "getDeclaredMethod(\"secret\"), setAccessible(true), then invoke", "getMethod(\"secret\") and setAccessible(true)", "It is impossible"], "answer": 1, "explanation": "getMethod only finds public methods; getDeclaredMethod finds private ones."}, {"id": 193, "section": 12, "type": "Scenario", "question": "A login query is built as \"SELECT * FROM users WHERE name='\" + n + \"' AND pwd='\" + p + \"'\". An attacker enters ' OR '1'='1 as the password. The best fix is:", "options": ["Keep Statement but remove spaces", "Use PreparedStatement with ? placeholders", "Use executeUpdate instead", "Convert the password to uppercase"], "answer": 1, "explanation": "Placeholders treat input as data, not SQL."}, {"id": 194, "section": 12, "type": "Trap", "question": "What happens with the following code?\n\nPreparedStatement ps = con.prepareStatement(\"SELECT * FROM emp WHERE id = ?\");\nps.setInt(0, 10);", "options": ["Works", "SQLException: parameter index out of range (indexes start at 1)", "Compile-time error", "NullPointerException"], "answer": 1, "explanation": "JDBC parameter indexes start at 1."}, {"id": 195, "section": 12, "type": "Trap", "question": "What happens with the following code?\n\nResultSet rs = ps.executeQuery();\nint id = rs.getInt(1); // next() was never called", "options": ["Returns the first row's id", "SQLException: cursor is before the first row", "Returns 0", "Returns null"], "answer": 1, "explanation": "The cursor starts before the first row; call rs.next() first."}, {"id": 196, "section": 12, "type": "Concept", "question": "To find the number and names of the columns returned by a query at runtime, use:", "options": ["DatabaseMetaData", "ResultSetMetaData", "ParameterMetaData", "Statement"], "answer": 1, "explanation": "ResultSetMetaData describes columns; DatabaseMetaData describes the database."}, {"id": 197, "section": 12, "type": "Scenario", "question": "A fund transfer debits account A (succeeds) and then the credit to account B fails with an SQLException. Auto-commit is left at its default. What is the result?", "options": ["Both operations are rolled back automatically", "The debit stays committed and the data is inconsistent", "Both operations are committed", "The JVM aborts the transaction"], "answer": 1, "explanation": "With auto-commit on, each statement commits immediately; use setAutoCommit(false), commit(), and rollback() in catch."}, {"id": 198, "section": 12, "type": "Concept", "question": "In JDBC 4.0+ with the driver JAR on the classpath:", "options": ["Class.forName(driverClass) is always mandatory", "Explicit driver loading is not needed; DriverManager finds it via the service loader", "The driver can never be auto-loaded", "Only PreparedStatement needs Class.forName"], "answer": 1, "explanation": "Service-loader discovery since JDBC 4.0."}, {"id": 199, "section": 12, "type": "Concept", "question": "Which interface is used to call a stored procedure with OUT parameters?", "options": ["Statement", "PreparedStatement", "CallableStatement", "ResultSetMetaData"], "answer": 2, "explanation": "CallableStatement supports registerOutParameter."}, {"id": 200, "section": 12, "type": "Concept", "question": "The Data Access Object (DAO) pattern is used to:", "options": ["Separate persistence (JDBC) code from business logic", "Speed up SQL queries automatically", "Pool database connections", "Generate SQL automatically"], "answer": 0, "explanation": "DAO encapsulates database access behind an interface."}]};
